WITH "table2_subq_cte" AS ( SELECT "k0", COALESCE(JSON_ARRAYAGG(json_doc FORMAT JSON ORDER BY "rn" RETURNING CLOB), TO_CLOB(JSON_ARRAY())) AS "data" FROM ( SELECT JSON_OBJECT('id' VALUE "TABLE2"."id" NULL ON NULL RETURNING VARCHAR2(4000)) AS json_doc, "TABLE2"."k0" AS "k0", "TABLE2"."rn" AS "rn" FROM ( SELECT "TABLE2"."id" AS "id", "TABLE2"."parent_id" AS "k0", ROW_NUMBER() OVER (PARTITION BY "TABLE2"."parent_id" ORDER BY "TABLE2"."id" ASC) AS "rn" FROM "DBO"."LEVEL2" "TABLE2" WHERE 1 = 1 ) "TABLE2" WHERE "TABLE2"."rn" <= 25 ) ranked_rows GROUP BY "k0" ), "table1_subq_cte" AS ( SELECT "k0", COALESCE(JSON_ARRAYAGG(json_doc FORMAT JSON ORDER BY "rn" RETURNING CLOB), TO_CLOB(JSON_ARRAY())) AS "data" FROM ( SELECT JSON_OBJECT('id' VALUE "TABLE1"."id", 'level2' VALUE COALESCE("table2_subq_cte"."data", TO_CLOB(JSON_ARRAY())) FORMAT JSON NULL ON NULL RETURNING CLOB) AS json_doc, "TABLE1"."k0" AS "k0", "TABLE1"."rn" AS "rn" FROM ( SELECT "TABLE1"."id" AS "id", "TABLE1"."parent_id" AS "k0", ROW_NUMBER() OVER (PARTITION BY "TABLE1"."parent_id" ORDER BY "TABLE1"."id" ASC) AS "rn" FROM "DBO"."LEVEL1" "TABLE1" WHERE 1 = 1 ) "TABLE1" LEFT OUTER JOIN "table2_subq_cte" ON "table2_subq_cte"."k0" = "TABLE1"."id" WHERE "TABLE1"."rn" <= 50 ) ranked_rows GROUP BY "k0" ) SELECT COALESCE(JSON_ARRAYAGG("json_doc" FORMAT JSON ORDER BY "__dab_ord" RETURNING CLOB), TO_CLOB(JSON_ARRAY())) AS "data" FROM ( SELECT JSON_OBJECT('id' VALUE "id", 'level1' VALUE "level1" FORMAT JSON NULL ON NULL RETURNING CLOB) AS "json_doc", ROWNUM AS "__dab_ord" FROM ( SELECT "TABLE0"."ID" AS "id", COALESCE("table1_subq_cte"."data", TO_CLOB(JSON_ARRAY())) AS "level1" FROM "DBO"."PARENTS" "TABLE0" LEFT OUTER JOIN "table1_subq_cte" ON "table1_subq_cte"."k0" = "TABLE0"."ID" WHERE 1 = 1 OFFSET 0 ROWS FETCH NEXT 100 ROWS ONLY ) ) "subq0"